const S={manifest:null,modules:{},errors:{},accountMap:new Map(),videoMap:new Map(),view:'accounts',account:null,filters:{q:'',medium:'all',label:'all',inclusion:'all'},videoQuery:'',videoStatus:'all',unassigned:false,page:1,trigger:null};
