const badge=x=>`<span class="badge ${esc(String(x||'unknown').replace(/[^a-z_]/g,''))}">${esc(human(x))}</span>`,caption=x=>`<p class="caption">${esc(x)}</p>`,empty=x=>`<div class="empty">${esc(x)}</div>`,error=x=>`<div class="error" role="alert">${esc(x)}</div>`,heading=(b,h,p)=>`<header><span class="eyebrow">${esc(b)}</span><h1>${esc(h)}</h1><p class="intro">${esc(p)}</p></header>`,section=(h,p,b)=>`<section class="section"><div class="section-head"><h2>${esc(h)}</h2><p>${esc(p)}</p></div>${b}</section>`,facts=rows=>`<dl class="facts">${rows.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${v}</dd>`).join('')}</dl>`,table=(label,head,rows)=>`<div class="table-wrap"><table aria-label="${esc(label)}"><thead><tr>${head.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${head.length}">No rows match this view.</td></tr>`}</tbody></table></div>`,inspect=(type,id,label='Inspect provenance')=>`<button type="button" class="text" data-inspect="${esc(type)}" data-id="${esc(id)}">${esc(label)}</button>`,link=(href,label)=>safeURL(href)?`<a href="${esc(safeURL(href))}" target="_blank" rel="noreferrer">${esc(label)}</a>`:'Unknown URL',accountLink=a=>`<a data-account="${esc(a.account_id)}" href="?account=${encodeURIComponent(a.account_id)}">${esc(accountName(a))}</a>`,options=(rows,current)=>rows.map(([v,l])=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(l)}</option>`).join(''),bar=(value,total,color)=>finite(value)&&finite(total)&&total>0?`<div class="track" aria-hidden="true"><span style="width:${Math.max(0,Math.min(100,100*value/total))}%;--bar:${color||'var(--green)'}"></span></div>`:'<span class="caption">No verified denominator</span>';
function url(view,params={}){const q=new URLSearchParams();if(view==='account')q.set('account',params.account);else q.set('view',view);for(const[k,v]of Object.entries(params))if(k!=='account'&&v!==null&&v!==undefined&&v!==''&&v!=='all')q.set(k,v);return'?'+q.toString()}
function route(){const q=new URLSearchParams(location.search);S.account=q.get('account');S.view=S.account?'account':q.get('view')||'accounts';for(const k of Object.keys(S.filters))S.filters[k]=q.get(k)||(k==='q'?'':'all');S.videoQuery=q.get('video_query')||'';S.videoStatus=q.get('video_status')||'all';S.unassigned=q.get('unassigned')==='1';}
