async function fetchJSON(file,d={}){if(!safePath(file))throw Error('Invalid public release path.');const r=await fetch(file,{cache:'no-cache'});if(!r.ok)throw Error(`${file}: HTTP ${r.status}`);const b=await r.arrayBuffer();if(d.bytes!==undefined&&b.byteLength!==d.bytes)throw Error(`${file}: release size mismatch`);if(d.sha256&&crypto.subtle){const h=[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(x=>x.toString(16).padStart(2,'0')).join('');if(h!==d.sha256)throw Error(`${file}: release hash mismatch`)}const x=JSON.parse(new TextDecoder().decode(b));if(x.synthetic===true)throw Error('Synthetic observations cannot replace a collection ledger.');return x}
