function filteredAccounts(){const q=S.filters.q.trim().toLowerCase();return accounts().filter(a=>(!q||[accountName(a),a.account_id,a.channel_id,...A(a.handles),...mediums(a),...labels(a)].join(' ').toLowerCase().includes(q))&&(S.filters.medium==='all'||mediums(a).includes(S.filters.medium))&&(S.filters.label==='all'||labels(a).includes(S.filters.label))&&(S.filters.inclusion==='all'||a.inclusion_status===S.filters.inclusion))}
function currentIDs(rows=filteredAccounts()){return unique(rows.flatMap(ids))}
function tabNames(a){return unique(['videos','shorts','streams',...Object.keys(a.tabs||{})])}
function tabLabel(tab){if(!tab)return'Unknown';return human(tab.enumeration_status||'unknown')+(tab.continuation_exhausted===true?' · continuation exhausted':'')}
function filterForm(){return `<form id="account-filters" class="filters"><label>Find a YouTube account<input id="search" type="search" value="${esc(S.filters.q)}" placeholder="Account, handle, channel ID or attribution"></label><label>Attributed medium<select id="medium"><option value="all">All attributions</option>${options(unique(accounts().flatMap(mediums)).sort().map(x=>[x,x]),S.filters.medium)}</select></label><label>Claimed label<select id="label"><option value="all">All claimed labels</option>${options(unique(accounts().flatMap(labels)).sort().map(x=>[x,x]),S.filters.label)}</select></label><label>Screening status<select id="inclusion"><option value="all">All screened / unscreened</option>${options(unique(accounts().map(a=>a.inclusion_status).filter(Boolean)).sort().map(x=>[x,human(x)]),S.filters.inclusion)}</select></label><div class="actions"><button type="submit">Apply filters</button><button type="button" class="secondary" id="clear-filters">Clear filters</button><button type="button" class="secondary" id="export-accounts">Export matching accounts CSV</button><button type="button" class="secondary" id="export-selection">Export selection JSON</button></div></form>`}
function overviewCounts(rows){const linked=currentIDs(rows),verified=unique(rows.flatMap(a=>ids(a).filter(id=>video(id)?.verified_uploader_account_id===a.account_id))),totals=rows.filter(a=>finite(a.uploaded_total));return `<div class="scope-strip"><div><strong>${number(rows.length)}</strong><span>reconciled account references</span></div><div><strong>${number(linked.length)}</strong><span>distinct associated video IDs</span></div><div><strong>${number(verified.length)}</strong><span>historically joined uploader IDs</span></div><div><strong>${number(totals.length)} / ${number(rows.length)}</strong><span>references with a verified upload total</span></div></div>`}
function accountTable(rows){return table('YouTube account census',['Account / identity evidence','Screening / medium context','Observed video IDs','Historically verified uploader IDs','IDs passing duration/exclusion screening','YouTube total uploads','Tab enumeration','Retained YouTube assets'],rows.map(a=>`<tr><th scope="row"><span class="account-name">${accountLink(a)}</span><small>${esc(A(a.handles).join(' · ')||a.channel_id||'Channel ID unresolved')}</small><small>${esc(human(a.identity_status))}</small></th><td>${badge(a.inclusion_status)}<small>${esc(mediums(a).join(' · ')||'Medium attribution unknown')}</small></td><td class="numeric">${number(a.counts?.observed_associated_video_ids??ids(a).length)}</td><td class="numeric">${number(a.counts?.historically_verified_uploader_video_ids)}</td><td class="numeric">${number(a.counts?.policy_eligible_associated_video_ids)}</td><td class="numeric">${number(a.uploaded_total)}</td><td>${tabNames(a).map(t=>`<small>${esc(t==='streams'?'Live':human(t))}: ${esc(tabLabel(a.tabs?.[t]))}</small>`).join('')}</td><td>${assetCell(a.account_id)}</td></tr>`).join(''))}
